import{_ as n,l as i,o as e,c as s,v as t,p as l,x as r,d as p,i as E,S as c}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"动态完备与复制","description":"","frontmatter":{"title":"动态完备与复制","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/dynamic-completeness.md","filePath":"econ/dynamic-completeness.md","lastUpdated":1789023840000}'),d={name:"econ/dynamic-completeness.md"};function m(h,a,A,B,_,u){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="动态完备与复制" tabindex="-1">动态完备与复制 <a class="header-anchor" href="#动态完备与复制" aria-label="Permalink to &quot;动态完备与复制&quot;">​</a></h1><div class="epigraph"><p>状态可以很多，证券可以很少：只要能沿信息到达再交易，动态策略可以张成静态菜单张不成的支付。</p><footer>—— Kreps, Multiperiod Securities and the Efficient Allocation of Risk, 1982；对照 Harrison–Pliska 的布朗完全性</footer></div><p><a href="/econ/equivalent-martingale-measure">上一课</a>写明：完全当且仅当 EMM 唯一。本课缺口是<strong>完全从何而来</strong>——不是一开始就列出 \\(S\\) 张 Arrow 证券，而是动态再交易。不重写 \\(\\mathbb{Q}\\) 的定义，不把复制写成限价簿上的对冲执行。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态一期，\\(J\\lt S\\) 则不完全，见 <a href="/econ/incomplete-markets-gei">GEI</a>。多期：信息是树（或域流 \\(\\mathcal{F}_t\\)）。每期可按当时价格调整持仓，终端支付是策略的积分。Kreps（1982）强调：动态完备指策略空间张成所有（平方可积、适应的）或有支付，不是指某期现货市场列全。Black–Scholes 的世界只有股票与债券两种证券，连续交易加布朗信息，却能复制欧式期权——因为信息由一个布朗生成，两种连续交易的资产恰好对准那个不确定性来源。</p><p>缺口是把「张成」从矩阵的列换成策略的随机积分。FTAP 第二定理现在有了内容：EMM 唯一 ⇔ 动态张成足够。</p><p><span class="marginnote">离散树：每个节点的分叉数不得超过当时可交易的独立风险资产数（加债券），否则局部不满秩。连续时间把这句话换成「风险源的个数 = 连续交易的风险资产个数」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>复制：找可积策略 \\(\\phi\\)，使终端 \\(x=x_0+\\int\\phi\\,\\mathrm{d}S\\) 且贴现财富为 \\(\\mathbb{Q}\\)–鞅（无注入）。完全则每个 \\(x\\) 有复制，价格是复制的初始成本，也等于 \\(\\mathrm{E}^{\\mathbb{Q}}[x/B]\\)。不完全则只有 \\(\\mathrm{span}\\) 里的 \\(x\\) 有唯一价格；其余只有超复制的上界与次复制的下界——连续时间课序的定价界再写。</p><p>与状态价格课对照：静态完全是 \\(S\\) 张 Arrow；动态完全是「信息有多宽、能交易多少次、有多少独立价格过程」。Radner 式逐期开市场，可以把不完全的静态菜单做完备——前提是每期分叉被当时证券覆盖。</p>',10)),(e(),l(c,null,{default:r(()=>[E(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20STAT%5B%22%E9%9D%99%E6%80%81%3A%20%E5%88%97%E6%95%B0%20vs%20%E7%8A%B6%E6%80%81%E6%95%B0%22%5D%20--%3E%20GEI%5B%22GEI%20%E4%B8%8D%E5%AE%8C%E5%85%A8%22%5D%0A%20%20DYN%5B%22%E5%8A%A8%E6%80%81%3A%20%E7%AD%96%E7%95%A5%E7%A7%AF%E5%88%86%22%5D%20--%3E%20SPAN%5B%22%E5%BC%A0%E6%88%90%E9%80%82%E5%BA%94%E6%94%AF%E4%BB%98%22%5D%0A%20%20SPAN%20--%3E%20UNIQ%5B%22EMM%20%E5%94%AF%E4%B8%80%22%5D%0A%20%20BR%5B%22%E4%B8%80%E4%B8%AA%E5%B8%83%E6%9C%97%20%2B%20%E8%BF%9E%E7%BB%AD%E4%BA%A4%E6%98%93%22%5D%20--%3E%20BS%5B%22%E8%82%A1%E7%A5%A8%E5%80%BA%E5%88%B8%E5%8D%B3%E5%8F%AF%E5%A4%8D%E5%88%B6%E6%9C%9F%E6%9D%83%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>不要把「连续交易」写成「没有买卖价差所以能复制」。连续是域流与路径的理想化；价差会破坏精确复制，那是 Constantinides 后课，不是本课把 FTAP 收回去。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是信息到达时重新配置。今天分不清的两个状态，明天若被分开，只要那时还有能区分它们的相对价格，就可以把财富挪到正确的枝上。静态菜单必须预先为每一枝准备一张证券；动态菜单用时间换证券数目。布朗之所以「一个噪声源」，是因为无穷小增量只有一个方向；再多一个独立布朗，就要再多一个连续交易的资产，否则不完全。</p><p>Kyle 的连续拍卖是信息泄漏过程，不是复制过程。不要把知情者的战略强度当成动态完备——完备是菜单与域流的关系，与是否有人知情无关。有私人信息时，对谁而言的域流可以不同，复制对做市端与对知情者不是同一策略。那是接口，本课用公共域流。</p><p><span class="marginnote">跳跃过程每个跳的幅度若是新方向，可能需要无穷多证券才能完全。 Merton 跳扩散的期权一般不能用股票债券精确复制——不完全，价格落在区间或靠均衡定 \\(m\\)。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证明随机积分的表示定理。后文 Merton 组合会在完全市场里当策略存在；CIR、Black–Scholes 作为均衡会给出具体的完全经济。也不要把动态完备写成「现实能连续对冲」——执行是量化栏。</p><p>下一课回到 Harrison–Kreps：他们如何把鞅定价从套利推到跨期信念，并允许异质预期下的投机。本课只钉张成。</p><p>后课默认：动态再交易可以完备静态上看起来缺列的市场；EMM 唯一与可复制是同一件事。价差与跳跃会破坏精确复制。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>动态完备是策略张成适应支付，不是静态 Arrow 证券列全。</li><li>风险源个数对齐连续交易的风险资产个数时，少量证券即可完全。</li><li>复制价格 = EMM 期望；不完全则区间。</li><li>出处：Kreps, 1982；Harrison and Pliska, 1981；对照 Black–Scholes。</li></ul>',11))])}const b=n(d,[["render",m]]);export{S as __pageData,b as default};
